/**
 * RFC 9457 Problem Details error classes and utilities.
 * Strictly conforms to RFC 9457 and openapi.yaml specifications.
 */

export interface ProblemDetails {
  /**
   * URI reference identifying the problem type.
   * Defaults to 'about:blank' if unspecified per RFC 9457.
   */
  type: string;
  /**
   * Short, human-readable summary of the problem type.
   */
  title: string;
  /**
   * The HTTP status code generated by the origin server.
   */
  status: number;
  /**
   * Human-readable explanation specific to this occurrence of the problem.
   */
  detail: string;
  /**
   * Optional distributed tracing identifier for log and trace correlation.
   */
  traceId?: string;
  /**
   * Additional RFC 9457 extension members.
   */
  [key: string]: unknown;
}

/**
 * Standard HTTP status phrases for fallback title resolution.
 */
export const HTTP_STATUS_PHRASES: Record<number, string> = {
  400: 'Bad Request',
  401: 'Unauthorized',
  402: 'Payment Required',
  403: 'Forbidden',
  404: 'Not Found',
  405: 'Method Not Allowed',
  406: 'Not Acceptable',
  408: 'Request Timeout',
  409: 'Conflict',
  410: 'Gone',
  415: 'Unsupported Media Type',
  422: 'Unprocessable Entity',
  429: 'Too Many Requests',
  500: 'Internal Server Error',
  501: 'Not Implemented',
  502: 'Bad Gateway',
  503: 'Service Unavailable',
  504: 'Gateway Timeout',
};

/**
 * Standard HTTP status fallback details.
 */
export const HTTP_STATUS_DETAILS: Record<number, string> = {
  400: 'The server could not understand the request due to invalid syntax.',
  401: 'Missing, invalid, or expired authentication token.',
  403: 'You do not have permission to access the requested resource.',
  404: 'The requested resource was not found on the server.',
  405: 'The request method is not supported for this route.',
  409: 'The request could not be completed due to a conflict with current resource state.',
  422: 'Schema validation failed or request payload was unprocessable.',
  429: 'Too many requests were received. Please slow down and try again.',
  500: 'An unexpected internal server error occurred.',
  501: 'The server does not support the functionality required to fulfill the request.',
  502: 'The server received an invalid response from an upstream server.',
  503: 'The service is temporarily unavailable. Please try again later.',
  504: 'The upstream server timed out while fulfilling the request.',
};

/**
 * Resolves standard HTTP status phrase for a given status code.
 */
export function getStatusPhrase(status: number): string {
  if (HTTP_STATUS_PHRASES[status]) {
    return HTTP_STATUS_PHRASES[status];
  }
  if (status >= 500) return 'Server Error';
  if (status >= 400) return 'Client Error';
  return 'HTTP Error';
}

/**
 * Resolves default detail message for a given status code.
 */
export function getDefaultDetailForStatus(status: number): string {
  if (HTTP_STATUS_DETAILS[status]) {
    return HTTP_STATUS_DETAILS[status];
  }
  return `Request failed with HTTP status ${status}.`;
}

/**
 * Error class representing an API failure, encapsulating HTTP status,
 * statusText, and a structured RFC 9457 ProblemDetails object.
 */
export class ApiError extends Error {
  readonly status: number;
  readonly statusText: string;
  readonly problemDetails: ProblemDetails;

  constructor(status: number, statusText: string, problemDetails: ProblemDetails) {
    const message = problemDetails.detail || problemDetails.title || statusText || `HTTP ${status}`;
    super(message);
    this.name = 'ApiError';
    this.status = status;
    this.statusText = statusText;
    this.problemDetails = problemDetails;

    // Restore prototype chain in transpiled ES/TypeScript
    Object.setPrototypeOf(this, new.target.prototype);
  }
}

/**
 * Type guard to verify whether an unknown error is an instance of ApiError.
 */
export function isApiError(error: unknown): error is ApiError {
  if (error instanceof ApiError) {
    return true;
  }
  return (
    typeof error === 'object' &&
    error !== null &&
    (error as ApiError).name === 'ApiError' &&
    typeof (error as ApiError).status === 'number' &&
    typeof (error as ApiError).statusText === 'string' &&
    typeof (error as ApiError).problemDetails === 'object' &&
    (error as ApiError).problemDetails !== null
  );
}

/**
 * Robustly extracts the distributed tracing ID from an error or its problem details.
 * Checks: (1) body.traceId, (2) body.trace_id, (3) problemDetails.traceId / trace_id.
 */
export function extractTraceId(error: unknown): string | undefined {
  if (!error || typeof error !== 'object') {
    return undefined;
  }

  if (isApiError(error)) {
    const fromPd = error.problemDetails.traceId ?? (error.problemDetails['trace_id'] as string | undefined);
    if (typeof fromPd === 'string' && fromPd.trim()) {
      return fromPd.trim();
    }
  }

  const errObj = error as Record<string, unknown>;

  // Direct traceId / trace_id on error object
  if (typeof errObj.traceId === 'string' && errObj.traceId.trim()) {
    return errObj.traceId.trim();
  }
  if (typeof errObj.trace_id === 'string' && errObj.trace_id.trim()) {
    return errObj.trace_id.trim();
  }

  // Nested in problemDetails / problem_details
  const pd = (errObj.problemDetails ?? errObj['problem_details']) as Record<string, unknown> | undefined;
  if (pd && typeof pd === 'object') {
    if (typeof pd.traceId === 'string' && pd.traceId.trim()) {
      return pd.traceId.trim();
    }
    if (typeof pd.trace_id === 'string' && pd.trace_id.trim()) {
      return pd.trace_id.trim();
    }
  }

  return undefined;
}

/**
 * Guarantees UI components always receive a structured ProblemDetails object
 * regardless of the thrown error type (ApiError, native Error, string, or unknown).
 */
export function toProblemDetails(error: unknown): ProblemDetails {
  if (isApiError(error)) {
    return error.problemDetails;
  }

  if (error && typeof error === 'object') {
    const obj = error as Record<string, unknown>;
    const errName = typeof obj.name === 'string' ? obj.name : '';
    const errMessage = typeof obj.message === 'string' ? obj.message : '';

    // Check for Abort cancellations
    if (errName === 'AbortError' || errMessage.toLowerCase().includes('aborted')) {
      return {
        type: 'about:blank',
        title: 'Request Aborted',
        status: 0,
        detail: errMessage || 'The request was aborted.',
      };
    }

    // Check for network disconnects / failed to fetch
    if (errName === 'TypeError' && errMessage.toLowerCase().includes('fetch')) {
      return {
        type: 'about:blank',
        title: 'Network Error',
        status: 0,
        detail: 'Unable to connect to the server. Please check your network connection.',
      };
    }

    // If it already matches the ProblemDetails interface directly
    if (
      typeof obj.type === 'string' &&
      typeof obj.title === 'string' &&
      typeof obj.status === 'number' &&
      typeof obj.detail === 'string'
    ) {
      return {
        type: obj.type,
        title: obj.title,
        status: obj.status,
        detail: obj.detail,
        traceId: extractTraceId(error),
      };
    }

    // If it has a nested problemDetails object
    if (obj.problemDetails && typeof obj.problemDetails === 'object') {
      const pd = obj.problemDetails as Record<string, unknown>;
      if (
        typeof pd.type === 'string' &&
        typeof pd.title === 'string' &&
        typeof pd.status === 'number' &&
        typeof pd.detail === 'string'
      ) {
        return {
          type: pd.type,
          title: pd.title,
          status: pd.status,
          detail: pd.detail,
          traceId: extractTraceId(error),
        };
      }
    }

    if (error instanceof Error || errName || errMessage) {
      return {
        type: 'about:blank',
        title: errName || 'Error',
        status: 500,
        detail: errMessage || 'An unexpected error occurred.',
        traceId: extractTraceId(error),
      };
    }
  }

  if (typeof error === 'string' && error.trim().length > 0) {
    return {
      type: 'about:blank',
      title: 'Error',
      status: 500,
      detail: error.trim(),
    };
  }

  return {
    type: 'about:blank',
    title: 'Unexpected Error',
    status: 500,
    detail: 'An unexpected error occurred. Please try again.',
  };
}
